#nullable enable // autogenerated

using MVZ2Logic.UI;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.Level.UI
{
    public class HeldTargetBubble : MonoBehaviour
    {
        public void SetVisible(bool visible)
        {
            gameObject.SetActive(visible);
        }
        public void SetContent(Sprite? sprite)
        {
            contentImage.SetSprite(sprite);
        }
        public void SetPosition(Vector2 position)
        {
            bubbleRoot.position = position;
            var localPos = bubbleRoot.localPosition;
            localPos.z = 0;
            bubbleRoot.localPosition = localPos;
        }
        [SerializeField]
        private Transform bubbleRoot = null!;
        [SerializeField]
        private ImageResolver contentImage = null!;
    }
}
